import { Component, Input, Output, EventEmitter } from '@angular/core';
import { Router } from '@angular/router';
import { SoftwarePackage } from '../../models/software-package';

@Component({
  selector: 'app-software-package-card',
  templateUrl: './software-package-card.component.html',
  styleUrls: ['./software-package-card.component.css']
})
export class SoftwarePackageCardComponent {
  @Input() package!: SoftwarePackage;
  @Output() click = new EventEmitter<SoftwarePackage>();

  constructor(private router: Router) {}

  onClick(): void {
    this.click.emit(this.package);
  }

  orderPackage(event: Event): void {
    event.stopPropagation();
    this.router.navigate(['/packages', this.package.id, 'order']);
  }
}
<div class="card-base">
  <div class="aspect-square bg-gray-100 overflow-hidden relative group">
    <img
      [src]="package.thumbnail || package.images?.[0] || 'https://via.placeholder.com/300'"
      [alt]="package.title"
      class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
    />
    <div class="absolute top-3 left-3 bg-black bg-opacity-60 text-white px-2 py-1 rounded text-[10px] font-medium">
      {{ package.category }}
    </div>
  </div>
  <div class="p-4">
    <h3 class="font-semibold text-gray-900 mb-2 line-clamp-2 text-sm">{{ package.title }}</h3>
    <div class="flex items-center gap-1.5 mb-3">
      <svg class="w-3 h-3 text-yellow-400" fill="currentColor" viewBox="0 0 20 20">
        <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
      </svg>
      <span class="text-xs text-gray-600">{{ package.rating || 'N/A' }}</span>
    </div>
    <button (click)="orderPackage($event)" class="w-full bg-primary text-white py-2.5 rounded-lg text-sm font-bold hover:bg-primary-dark transition-colors shadow-sm">
      Order Now
    </button>
    <p class="text-xs text-gray-500 line-clamp-2 mt-2">{{ package.description }}</p>
  </div>
</div>
